import { subscribe } from '../events.js';
import { telemetryBuffer } from './buffer.js';
import { telemetrySender } from './sender.js';
import { PRIORITY_LEVELS } from './priority.js';

export function initTelemetryPipeline() {
  telemetrySender.start();

  subscribe((event) => {
    // Skip events already generated by the telemetry pipeline itself to avoid loops
    if (event.category === 'telemetry') return;

    // Add to buffer
    const priority = telemetryBuffer.addEvent(event);

    // If high priority, transmit immediately
    if (priority === PRIORITY_LEVELS.HIGH) {
      telemetrySender.sendImmediate(event);
      // Remove it from the high buffer since we just sent it
      const buf = telemetryBuffer.getBuffer();
      buf.high = buf.high.filter(e => e.id !== event.id);
    }
  });
}

export function stopTelemetryPipeline() {
  telemetrySender.stop();
}
